window.__POLYGON_SCRIPT_V2_PARTS__ = window.__POLYGON_SCRIPT_V2_PARTS__ || [];
window.__POLYGON_SCRIPT_V2_PARTS__.push("            <button class=\"small-button\" type=\"button\" data-action=\"create-unit\" title=\"Создать юнита\" aria-label=\"Создать юнита\">+</button>\n            <button class=\"small-button\" type=\"button\" data-unit-action=\"toggle-list\" title=\"Открыть список юнитов\">${iconSvg('list')} <span>Юниты ${state.units.length}</span></button>\n            <button class=\"action-button\" type=\"button\" data-unit-action=\"open-details\" title=\"Открыть подробные настройки\" ${unit ? '' : 'disabled'}>Подробно</button>\n          </div>`;\n\n        if (!unit) {\n          return `\n            <div class=\"unit-editor-shell\">\n              ${toolbar}\n              ${unitListPopover()}\n              <div class=\"unit-editor-scroll\">\n                <div class=\"unit-editor-empty\">\n                  <div><strong>Юнит не выбран</strong><p>Выберите бойца на карте, откройте скрытый список или создайте нового.</p><button class=\"small-button\" type=\"button\" data-action=\"create-unit\">Создать и разместить</button></div>\n                </div>\n              </div>\n            </div>`;\n        }\n\n        return `\n          <div class=\"unit-editor-shell\">\n            ${toolbar}\n            ${unitListPopover()}\n            <div class=\"unit-editor-scroll\">\n              <div class=\"unit-card-head\">\n                <div class=\"unit-card-avatar\">${escapeHtml(unit.short)}</div>\n                <div class=\"unit-card-copy\"><div class=\"unit-card-name\">${escapeHtml(unit.name)}</div><div class=\"unit-card-meta\">${escapeHtml(unit.sideLabel)} · ${escapeHtml(unit.archetype)}</div></div>\n                <div class=\"unit-quick-actions\">\n                  <button class=\"icon-tool\" type=\"button\" data-unit-action=\"locate\" title=\"Найти на карте\" aria-label=\"Найти на карте\">${iconSvg('locate')}</button>\n                  <button class=\"icon-tool\" type=\"button\" data-unit-action=\"move\" title=\"Переместить\" aria-label=\"Переместить\">${iconSvg('move')}</button>\n                  <button class=\"icon-tool\" type=\"button\" data-unit-action=\"rotate\" title=\"Повернуть\" aria-label=\"Повернуть\">${iconSvg('rotate')}</button>\n                </div>\n              </div>\n\n              <section class=\"compact-section\">\n                <div class=\"compact-section__head\"><span class=\"compact-section__title\">Основное</span><div class=\"unit-quick-actions\"><button class=\"icon-tool\" type=\"button\" data-unit-action=\"copy\" title=\"Копировать\" aria-label=\"Копировать\">${iconSvg('copy')}</button><button class=\"icon-tool icon-tool--danger\" type=\"button\" data-unit-action=\"delete\" title=\"Удалить\" aria-label=\"Удалить\">${iconSvg('trash')}</button></div></div>\n                <div class=\"compact-section__body\">\n                  <div class=\"compact-grid\">\n                    <div class=\"compact-field compact-field--wide\"><label>Имя</label><input value=\"${escapeHtml(unit.name)}\" data-unit-field=\"name\"></div>\n                    <div class=\"compact-field\"><label>Сторона</label><select data-unit-field=\"side\"><option value=\"blue\" ${unit.side === 'blue' ? 'selected' : ''}>Синие</option><option value=\"red\" ${unit.side === 'red' ? 'selected' : ''}>Красные</option><option value=\"neutral\" ${unit.side === 'neutral' ? 'selected' : ''}>Нейтральные</option></select></div>\n                    <div class=\"compact-field\"><label>Архетип</label><select data-unit-field=\"archetype\">${optionList(Object.keys(archetypeProfileSets), unit.archetype)}</select></div>\n                    <div class=\"compact-field compact-field--wide\"><label>Положение тела</label><div class=\"pose-tools\">\n                      <button class=\"icon-tool ${unit.pose === 'stand' ? 'is-active' : ''}\" type=\"button\" data-unit-pose=\"stand\" title=\"Стоит\" aria-label=\"Стоит\">${iconSvg('stand')}</button>\n                      <button class=\"icon-tool ${unit.pose === 'crouch' ? 'is-active' : ''}\" type=\"button\" data-unit-pose=\"crouch\" title=\"Сидит\" aria-label=\"Сидит\">${iconSvg('crouch')}</button>\n                      <button class=\"icon-tool ${unit.pose === 'prone' ? 'is-active' : ''}\" type=\"button\" data-unit-pose=\"prone\" title=\"Лежит\" aria-label=\"Лежит\">${iconSvg('prone')}</button>\n                    </div></div>\n                  </div>\n                  <div class=\"profile-set-note\">Архетип назначает исходный набор профилей. Для этого юнита их можно заменить ниже.</div>\n                </div>\n              </section>\n\n              <section class=\"compact-section\">\n                <div class=\"compact-section__head\"><span class=\"compact-section__title\">Набор профилей</span></div>\n                <div class=\"compact-section__body\"><div class=\"compact-grid\">\n                  <div class=\"compact-field compact-field--wide\"><label>Поведение</label><select data-unit-field=\"behaviorProfile\">${optionList(profileOptions.behaviorProfile, unit.behaviorProfile)}</select></div>\n                  <div class=\"compact-field\"><label>Внимание</label><select data-unit-field=\"attentionProfile\">${optionList(profileOptions.attentionProfile, unit.attentionProfile)}</select></div>\n                  <div class=\"compact-field\"><label>Движение</label><select data-unit-field=\"movementProfile\">${optionList(profileOptions.movementProfile, unit.movementProfile)}</select></div>\n                </div></div>\n              </section>\n\n              <section class=\"compact-section\">\n                <div class=\"compact-section__head\"><span class=\"compact-section__title\">Вооружение</span></div>\n                <div class=\"compact-section__body\"><div class=\"compact-grid\">\n                  <div class=\"compact-field compact-field--wide\"><label>Основное оружие</label><select data-unit-field=\"weapon\">${optionList(['Винтовка Мосина','ППШ-41','Пулемёт ДП-27','Пистолет ТТ','Карабин 98k','Не задано'], unit.weapon)}</select></div>\n                  <div class=\"compact-field\"><label>В оружии</label><input type=\"number\" min=\"0\" value=\"${unit.loadedAmmo}\" data-unit-field=\"loadedAmmo\"></div>\n                  <div class=\"compact-field\"><label>В запасе</label><input type=\"number\" min=\"0\" value=\"${unit.reserveAmmo}\" data-unit-field=\"reserveAmmo\"></div>\n                </div></div>\n              </section>\n\n              <section class=\"compact-section\">\n                <div class=\"compact-section__head\"><span class=\"compact-section__title\">Начальное состояние</span></div>\n                <div class=\"compact-section__body\"><div class=\"compact-grid compact-grid--three\">\n                  <div class=\"compact-field\"><label>Здоровье, %</label><input type=\"number\" min=\"0\" max=\"100\" value=\"${unit.health}\" data-unit-field=\"health\"></div>\n                  <div class=\"compact-field\"><label>Подавление, %</label><input type=\"number\" min=\"0\" max=\"100\" value=\"${unit.suppression}\" data-unit-field=\"suppression\"></div>\n                  <div class=\"compact-field\"><label>Усталость, %</label><input type=\"number\" min=\"0\" max=\"100\" value=\"${unit.fatigue}\" data-unit-field=\"fatigue\"></div>\n                  <div class=\"compact-field\"><label>Боевой дух, %</label><input type=\"number\" min=\"0\" max=\"100\" value=\"${unit.morale}\" data-unit-field=\"morale\"></div>\n                  <div class=\"compact-field\"><label>Осмотр, сек</label><input type=\"number\" min=\"0\" max=\"120\" value=\"${unit.awarenessSeconds}\" data-unit-field=\"awarenessSeconds\"></div>\n                  <div class=\"compact-field\"><label>Ранения</label><select data-unit-field=\"injuries\">${optionList(['Нет','Лёгкое','Среднее','Тяжёлое'], unit.injuries)}</select></div>\n                </div></div>\n              </section>\n            </div>\n          </div>`;\n      }\n\n      function unresolvedTemplate(title) {\n        return `\n          <div class=\"empty-state\">\n            <div>\n              <div class=\"empty-state__icon\">◇</div>\n              <strong>${escapeHtml(title)}</strong>\n              <p>Содержимое раздела пока оставлено пустым.</p>\n            </div>\n          </div>`;\n      }\n\n      function renderWorkspace() {\n        const templates = {\n          'program': programTemplate,\n          'map-editor': mapEditorTemplate,\n          'unit-editor': unitEditorTemplate,\n          'series': () => unresolvedTemplate('Серия'),\n          'metrics': () => unresolvedTemplate('Метрики'),\n          'journal': () => unresolvedTemplate('Журнал')\n        };\n        els.leftPanelContent.innerHTML = templates[state.workspace]();\n      }\n\n      function renderUnits() {\n        els.unitLayer.innerHTML = state.units.map(unit => `\n          <button\n            class=\"unit-marker ${state.selectedUnitId === unit.id ? 'is-selected' : ''}\"\n            style=\"left:${unit.x}%;top:${unit.y}%;--heading:${unit.heading}deg\"\n            type=\"button\"\n            data-unit-id=\"${unit.id}\"\n            data-side=\"${unit.side}\"\n            aria-label=\"Выбрать юнита ${escapeHtml(unit.name)}\">\n            ${escapeHtml(unit.short)}\n            <span class=\"unit-label\">${escapeHtml(unit.name)}</span>\n          </button>`).join('');\n      }\n\n      function renderMarkers() {\n        els.markerLayer.innerHTML = state.experiment.markers.map(marker => `\n          <span class=\"map-marker map-marker--${marker.type}\" style=\"left:${marker.x}%;top:${marker.y}%\" title=\"${escapeHtml(marker.label)}\"></span>`\n        ).join('');\n      }\n\n      function selectedUnit() {\n        return state.units.find(unit => unit.id === state.selectedUnitId) || null;\n      }\n\n      function inspectorBody(unit) {\n        const blank = (title) => `\n          <div class=\"empty-state\">\n            <div>\n              <div class=\"empty-state__icon\">·</div>\n              <strong>${escapeHtml(title)}</strong>\n              <p>Подробное содержимое этой информационной вкладки пока не переносилось в прототип.</p>\n            </div>\n          </div>`;\n\n        if (state.inspector === 'info') {\n          return `\n            <div class=\"panel-scroll\">\n              <section class=\"section\">\n                <div class=\"section__head\"><span class=\"section__title\">Текущее состояние</span><span class=\"status-chip\">${escapeHtml(unit.state)}</span></div>\n");
